						"position": {
							"x": 730,
							"y": 342,
							"w": 690,
							"h": 408
						},
						"type": "block"
					},
					{
						"item": "viz_secure_networking_zta_ztna_device_category_outcomes",
						"position": {
							"x": 20,
							"y": 770,
							"w": 690,
							"h": 408
						},
						"type": "block"
					},
					{
						"item": "viz_secure_networking_zta_ztna_connection_status_trend",
						"position": {
