						"type": "block"
					},
					{
						"item": "viz_network_nvm_top_users_by_egress",
						"position": {
							"x": 20,
							"y": 2054,
							"w": 690,
							"h": 408
						},
						"type": "block"
					},
					{
						"item": "viz_secure_networking_zta_duo_auth_outcomes_by_application",
						"position": {
