							"y": 2054,
							"w": 690,
							"h": 408
						},
						"type": "block"
					},
					{
						"item": "viz_secure_networking_infra_secure_endpoint_incidents",
						"position": {
							"x": 20,
							"y": 2482,
							"w": 690,
							"h": 408
						},
						"type": "block"
					},
					{
						"item": "viz_secure_networking_infra_duo_blocked_posture_identity",
						"position": {
							"x": 730,
							"y": 2482,
							"w": 690,
							"h": 408
						},
						"type": "block"
					},
					{
						"item": "viz_secure_networking_infra_duo_application_access",
						"position": {
							"x": 20,
							"y": 2910,
							"w": 690,
							"h": 408
						},
						"type": "block"
					}
				],
				"type": "absolute"
			}
		},
		"options": {
			"showTitleAndDescription": false,
			"submitButton": false,
			"submitOnDashboardLoad": true
		},
		"tabs": {
			"items": [
				{
					"label": "overview",
					"layoutId": "layout_overview"
				}
			]
		}
	},
	"applicationProperties": {
		"collapseNavigation": false,
		"hideEdit": false,
		"hideExport": false
	}
}
